<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,HttpException,RuntimeContext};

final class SiteAssuranceService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly ?WorkflowLanguageService $languages=null) {}

    public function list(string $resource): array {
        $queries=[
            'instructions'=>'SELECT instruction_id,site_id,revision,title,instructions,emergency_contacts,published_at,created_by_user_id FROM site_instruction_versions WHERE company_id=:company ORDER BY instruction_id DESC LIMIT 500',
            'acknowledgements'=>'SELECT a.instruction_id,v.site_id,v.revision,a.user_id,a.acknowledged_at FROM site_instruction_acknowledgements a JOIN site_instruction_versions v ON v.instruction_id=a.instruction_id AND v.company_id=a.company_id WHERE a.company_id=:company ORDER BY a.acknowledgement_id DESC LIMIT 500',
            'handovers'=>'SELECT * FROM shift_handovers WHERE company_id=:company ORDER BY handover_id DESC LIMIT 500',
            'competencies'=>'SELECT * FROM training_competencies WHERE company_id=:company ORDER BY competency_code LIMIT 500',
            'requirements'=>'SELECT r.*,c.competency_name FROM site_training_requirements r JOIN training_competencies c ON c.competency_id=r.competency_id AND c.company_id=r.company_id WHERE r.company_id=:company AND r.removed_at IS NULL ORDER BY r.site_id,r.requirement_id LIMIT 500',
            'training'=>'SELECT * FROM employee_training WHERE company_id=:company ORDER BY valid_until,training_id LIMIT 500',
            'maintenance'=>'SELECT * FROM maintenance_tickets WHERE company_id=:company ORDER BY ticket_id DESC LIMIT 500',
            'service-targets'=>'SELECT * FROM site_service_targets WHERE company_id=:company ORDER BY effective_from DESC,target_id DESC LIMIT 500',
        ];
        if(!isset($queries[$resource]))throw HttpException::notFound();return $this->db->fetchAll($queries[$resource],['company'=>$this->company()]);
    }
    public function publishInstructions(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['site_id','expected_revision','title','instructions','emergency_contacts']);$site=$this->site($input['site_id']??null);$last=$this->db->fetch('SELECT revision FROM site_instruction_versions WHERE company_id=:company AND site_id=:site ORDER BY revision DESC LIMIT 1',['company'=>$this->company(),'site'=>$site['site_id']]);$revision=(int)($last['revision']??0);
        if($this->number($input['expected_revision']??null,0)!==$revision)throw HttpException::conflict('Instructions changed. Refresh the current revision.');
        $this->db->execute('INSERT INTO site_instruction_versions(company_id,site_id,revision,title,instructions,emergency_contacts,created_by_user_id,published_at) VALUES(:company,:site,:revision,:title,:instructions,:contacts,:actor,:now)',['company'=>$this->company(),'site'=>$site['site_id'],'revision'=>$revision+1,'title'=>$this->text($input['title']??null,150),'instructions'=>$this->text($input['instructions']??null,16000),'contacts'=>$this->text($input['emergency_contacts']??null,4000),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('site_instructions')+['revision'=>$revision+1];
    });}
    private function assignedSite(int $site): void {
        if(!$this->db->fetch("SELECT shift_assignment_id FROM shift_assignments WHERE company_id=:company AND employee_id=:employee AND site_id=:site AND deleted_at IS NULL AND assignment_status IN ('ASSIGNED','CONFIRMED','IN_PROGRESS') AND shift_end_at>=:now AND shift_start_at<=:until LIMIT 1",['company'=>$this->company(),'employee'=>$this->employee(),'site'=>$site,'now'=>gmdate('Y-m-d H:i:s'),'until'=>gmdate('Y-m-d H:i:s',time()+7*86400)]))throw HttpException::notFound('No current or upcoming site duty.');
    }
    public function acknowledgeInstructions(string $id): array {return $this->atomic(function()use($id){
        $version=$this->row('site_instruction_versions','instruction_id',$id);$this->assignedSite((int)$version['site_id']);$latest=$this->db->fetch('SELECT instruction_id FROM site_instruction_versions WHERE company_id=:company AND site_id=:site ORDER BY revision DESC LIMIT 1',['company'=>$this->company(),'site'=>$version['site_id']]);if((string)$latest['instruction_id']!==$id)throw HttpException::conflict('A newer instruction revision must be read.');
        $keys=['company'=>$this->company(),'instruction'=>$id,'actor'=>$this->actor()];if(!$this->db->fetch('SELECT acknowledgement_id FROM site_instruction_acknowledgements WHERE company_id=:company AND instruction_id=:instruction AND user_id=:actor',$keys))$this->db->execute('INSERT INTO site_instruction_acknowledgements(company_id,instruction_id,user_id,acknowledged_at) VALUES(:company,:instruction,:actor,:now)',$keys+['now'=>gmdate('Y-m-d H:i:s')]);$this->audit->record('site_instructions','acknowledged',$id);return ['acknowledged'=>true,'revision'=>$version['revision']];
    });}
    public function guardWorkspace(): array {
        $employee=$this->employee();$instructions=$this->db->fetchAll("SELECT DISTINCT v.instruction_id,v.site_id,v.revision,v.title,v.instructions,v.emergency_contacts,v.published_at FROM site_instruction_versions v JOIN shift_assignments s ON s.company_id=v.company_id AND s.site_id=v.site_id WHERE v.company_id=:company AND s.employee_id=:employee AND s.deleted_at IS NULL AND s.assignment_status IN ('ASSIGNED','CONFIRMED','IN_PROGRESS') AND s.shift_end_at>=:now AND s.shift_start_at<=:until AND NOT EXISTS(SELECT 1 FROM site_instruction_versions newer WHERE newer.company_id=v.company_id AND newer.site_id=v.site_id AND newer.revision>v.revision) ORDER BY v.site_id LIMIT 100",['company'=>$this->company(),'employee'=>$employee,'now'=>gmdate('Y-m-d H:i:s'),'until'=>gmdate('Y-m-d H:i:s',time()+7*86400)]);
        foreach($instructions as&$v)$v['acknowledged']=(bool)$this->db->fetch('SELECT acknowledgement_id FROM site_instruction_acknowledgements WHERE company_id=:company AND instruction_id=:id AND user_id=:actor',['company'=>$this->company(),'id'=>$v['instruction_id'],'actor'=>$this->actor()]);unset($v);
        $handovers=$this->db->fetchAll('SELECT * FROM shift_handovers WHERE company_id=:company AND (sender_employee_id=:sender OR receiver_employee_id=:receiver) ORDER BY handover_id DESC LIMIT 100',['company'=>$this->company(),'sender'=>$employee,'receiver'=>$employee]);foreach($handovers as&$h)$h['can_accept']=$h['accepted_at']===null&&(string)$h['receiver_employee_id']===$employee;unset($h);
        if($this->languages!==null)foreach($instructions as&$instruction){$t=$this->languages->read(['entity_kind'=>'INSTRUCTION','entity_id'=>$instruction['instruction_id']],true);$instruction=array_merge($instruction,$t['content'],['display_language'=>$t['display_language'],'translation_fallback'=>$t['fallback']]);}unset($instruction);
        return ['instructions'=>$instructions,'handovers'=>$handovers,'training'=>$this->db->fetchAll('SELECT t.training_id,t.competency_id,c.competency_name,t.valid_from,t.valid_until,t.verified_at,t.revoked_at FROM employee_training t JOIN training_competencies c ON c.company_id=t.company_id AND c.competency_id=t.competency_id WHERE t.company_id=:company AND t.employee_id=:employee ORDER BY t.valid_until LIMIT 200',['company'=>$this->company(),'employee'=>$employee])];
    }
    public function createHandover(array $input,bool $self=false): array {return $this->atomic(function()use($input,$self){
        $this->fields($input,['source_shift_id','target_shift_id','keys_summary','equipment_summary','open_incident_ids','outstanding_tasks']);$source=$self?$this->ownShift($input['source_shift_id']??null):$this->row('shift_assignments','shift_assignment_id',$input['source_shift_id']??null);$target=$this->row('shift_assignments','shift_assignment_id',$input['target_shift_id']??null);
        if(empty($source['site_id'])||(string)$source['site_id']!==(string)$target['site_id']||(string)$source['employee_id']===(string)$target['employee_id']||!empty($source['deleted_at'])||!empty($target['deleted_at'])||in_array($source['assignment_status'],['CANCELLED','MISSED'],true)||!in_array($target['assignment_status'],['ASSIGNED','CONFIRMED','IN_PROGRESS'],true)||$target['shift_start_at']<$source['shift_start_at']||abs(strtotime($target['shift_start_at'].' UTC')-strtotime($source['shift_end_at'].' UTC'))>86400)throw HttpException::unprocessable('Choose successive shifts for different guards at the same site, within 24 hours of handover.');
        $ids=$input['open_incident_ids']??[];if(!is_array($ids)||!array_is_list($ids)||count($ids)>30)throw HttpException::unprocessable('Choose up to 30 incident identifiers.');$clean=[];foreach($ids as$id){$incident=$this->row('incidents','incident_id',$id);if((string)$incident['site_id']!==(string)$source['site_id']||!empty($incident['deleted_at'])||in_array($incident['status'],['CLOSED','CANCELLED','RESOLVED'],true))throw HttpException::unprocessable('Handover incidents must be open at this site.');$clean[]=(int)$incident['incident_id'];}$clean=array_values(array_unique($clean));
        if($this->db->fetch('SELECT handover_id FROM shift_handovers WHERE company_id=:company AND source_shift_id=:source AND target_shift_id=:target',['company'=>$this->company(),'source'=>$source['shift_assignment_id'],'target'=>$target['shift_assignment_id']]))throw HttpException::conflict('This shift handover already exists.');
        $this->db->execute('INSERT INTO shift_handovers(company_id,source_shift_id,target_shift_id,site_id,sender_employee_id,receiver_employee_id,keys_summary,equipment_summary,open_incident_ids,outstanding_tasks,created_by_user_id,created_at) VALUES(:company,:source,:target,:site,:sender,:receiver,:keys,:equipment,:incidents,:tasks,:actor,:now)',['company'=>$this->company(),'source'=>$source['shift_assignment_id'],'target'=>$target['shift_assignment_id'],'site'=>$source['site_id'],'sender'=>$source['employee_id'],'receiver'=>$target['employee_id'],'keys'=>$this->text($input['keys_summary']??null,1000),'equipment'=>$this->text($input['equipment_summary']??null,1000),'incidents'=>json_encode($clean,JSON_THROW_ON_ERROR),'tasks'=>$this->text($input['outstanding_tasks']??null,4000),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('shift_handover');
    });}
    public function acceptHandover(string $id,array $input): array {return $this->atomic(function()use($id,$input){
        $this->fields($input,['receiver_notes']);$handover=$this->row('shift_handovers','handover_id',$id);$target=$this->ownShift($handover['target_shift_id']);if((string)$handover['receiver_employee_id']!==$this->employee()||(string)$target['employee_id']!==(string)$handover['receiver_employee_id'])throw HttpException::notFound();if($handover['accepted_at']!==null)throw HttpException::conflict('Handover already accepted.');$now=gmdate('Y-m-d H:i:s');if($now<gmdate('Y-m-d H:i:s',strtotime($target['shift_start_at'].' UTC')-3600)||$now>$target['shift_end_at'])throw HttpException::conflict('Accept within one hour before or during the receiving shift.');
        $this->db->execute('UPDATE shift_handovers SET accepted_at=:now,accepted_by_user_id=:actor,receiver_notes=:notes WHERE company_id=:company AND handover_id=:id',['now'=>$now,'actor'=>$this->actor(),'notes'=>$this->text($input['receiver_notes']??null,1000),'company'=>$this->company(),'id'=>$id]);$this->audit->record('shift_handover','accepted',$id);return ['accepted'=>true];
    });}
    public function competency(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['competency_code','competency_name']);$code=strtoupper($this->text($input['competency_code']??null,60));if(!preg_match('/^[A-Z0-9_-]+$/D',$code))throw HttpException::unprocessable('Use letters, digits, underscores or hyphens for the competency code.');if($this->db->fetch('SELECT competency_id FROM training_competencies WHERE company_id=:company AND competency_code=:code',['company'=>$this->company(),'code'=>$code]))throw HttpException::conflict('Competency code already exists.');$this->db->execute('INSERT INTO training_competencies(company_id,competency_code,competency_name) VALUES(:company,:code,:name)',['company'=>$this->company(),'code'=>$code,'name'=>$this->text($input['competency_name']??null,150)]);return $this->created('training_competency');
    });}
    public function requireTraining(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['site_id','competency_id']);$site=$this->site($input['site_id']??null);$competency=$this->row('training_competencies','competency_id',$input['competency_id']??null);$keys=['company'=>$this->company(),'site'=>$site['site_id'],'competency'=>$competency['competency_id']];$existing=$this->db->fetch('SELECT requirement_id FROM site_training_requirements WHERE company_id=:company AND site_id=:site AND competency_id=:competency',$keys);if($existing){$this->db->execute('UPDATE site_training_requirements SET removed_at=NULL WHERE company_id=:company AND site_id=:site AND competency_id=:competency',$keys);$this->audit->record('site_training_requirement','restored',(string)$existing['requirement_id']);return ['id'=>(string)$existing['requirement_id']];}$this->db->execute('INSERT INTO site_training_requirements(company_id,site_id,competency_id) VALUES(:company,:site,:competency)',$keys);return $this->created('site_training_requirement');
    });}
    public function removeRequirement(string $id): array {return $this->atomic(function()use($id){$this->row('site_training_requirements','requirement_id',$id);$this->db->execute('UPDATE site_training_requirements SET removed_at=:now WHERE company_id=:company AND requirement_id=:id',['now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$id]);$this->audit->record('site_training_requirement','removed',$id);return ['removed'=>true];});}
    public function recordTraining(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['employee_id','competency_id','reference_number','valid_from','valid_until']);$employee=$this->row('employees','employee_id',$input['employee_id']??null);$competency=$this->row('training_competencies','competency_id',$input['competency_id']??null);$from=$this->day($input['valid_from']??null);$until=$this->day($input['valid_until']??null);if($until<$from)throw HttpException::unprocessable('Training expiry must follow its start.');$this->db->execute('INSERT INTO employee_training(company_id,employee_id,competency_id,reference_number,valid_from,valid_until) VALUES(:company,:employee,:competency,:reference,:start,:end)',['company'=>$this->company(),'employee'=>$employee['employee_id'],'competency'=>$competency['competency_id'],'reference'=>$this->text($input['reference_number']??null,150),'start'=>$from,'end'=>$until]);return $this->created('employee_training');
    });}
    public function verifyTraining(string $id): array {return $this->atomic(function()use($id){$r=$this->row('employee_training','training_id',$id);if($r['revoked_at']!==null)throw HttpException::conflict('Revoked training cannot be verified.');$this->db->execute('UPDATE employee_training SET verified_at=:now,verified_by_user_id=:actor WHERE company_id=:company AND training_id=:id',['now'=>gmdate('Y-m-d H:i:s'),'actor'=>$this->actor(),'company'=>$this->company(),'id'=>$id]);$this->audit->record('employee_training','manually_verified',$id);return ['verified'=>true,'note'=>'Manual evidence review; no external accreditation service was queried.'];});}
    public function revokeTraining(string $id,array $input): array {return $this->atomic(function()use($id,$input){$this->fields($input,['reason']);$this->row('employee_training','training_id',$id);$this->db->execute('UPDATE employee_training SET revoked_at=:now,revoked_by_user_id=:actor,revocation_reason=:reason WHERE company_id=:company AND training_id=:id AND revoked_at IS NULL',['now'=>gmdate('Y-m-d H:i:s'),'actor'=>$this->actor(),'reason'=>$this->text($input['reason']??null),'company'=>$this->company(),'id'=>$id]);$this->audit->record('employee_training','revoked',$id);return ['revoked'=>true];});}
    public function trainingGaps(): array {
        $rows=$this->db->fetchAll("SELECT s.shift_assignment_id,s.site_id,s.employee_id,s.shift_start_at,s.shift_end_at,r.competency_id,c.competency_name FROM shift_assignments s JOIN site_training_requirements r ON r.company_id=s.company_id AND r.site_id=s.site_id AND r.removed_at IS NULL JOIN training_competencies c ON c.company_id=r.company_id AND c.competency_id=r.competency_id WHERE s.company_id=:company AND s.deleted_at IS NULL AND s.assignment_status IN ('ASSIGNED','CONFIRMED','IN_PROGRESS') AND s.shift_end_at>=:now AND s.shift_start_at<=:until ORDER BY s.shift_start_at,s.shift_assignment_id LIMIT 2001",['company'=>$this->company(),'now'=>gmdate('Y-m-d H:i:s'),'until'=>gmdate('Y-m-d H:i:s',time()+30*86400)]);
        if(count($rows)>2000)throw HttpException::unprocessable('More than 2000 upcoming shift requirements. Review a smaller roster before using this dashboard.');$gaps=[];foreach($rows as$r){if(!$this->db->fetch('SELECT training_id FROM employee_training WHERE company_id=:company AND employee_id=:employee AND competency_id=:competency AND verified_at IS NOT NULL AND revoked_at IS NULL AND valid_from<=:start AND valid_until>=:end LIMIT 1',['company'=>$this->company(),'employee'=>$r['employee_id'],'competency'=>$r['competency_id'],'start'=>substr($r['shift_start_at'],0,10),'end'=>substr($r['shift_end_at'],0,10)]))$gaps[]=$r;}return $gaps;
    }
    public function createTicket(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['site_id','equipment_id','asset_type','title','description','priority','assignee_user_id']);$site=$this->site($input['site_id']??null);$assignee=$this->row('users','user_id',$input['assignee_user_id']??null);if($assignee['status']!=='ACTIVE')throw HttpException::unprocessable('Choose an active assignee.');$equipment=empty($input['equipment_id'])?null:$this->row('equipment_items','equipment_id',$input['equipment_id'])['equipment_id'];if(!in_array($input['asset_type']??null,['RADIO','GATE','CAMERA','VEHICLE','OTHER'],true)||!in_array($input['priority']??null,['LOW','MEDIUM','HIGH','CRITICAL'],true))throw HttpException::unprocessable('Invalid asset type or priority.');$now=gmdate('Y-m-d H:i:s');
        $this->db->execute("INSERT INTO maintenance_tickets(company_id,site_id,equipment_id,asset_type,title,description,priority,assignee_user_id,state,created_by_user_id,created_at,updated_at) VALUES(:company,:site,:equipment,:type,:title,:description,:priority,:assignee,'ASSIGNED',:actor,:created,:updated)",['company'=>$this->company(),'site'=>$site['site_id'],'equipment'=>$equipment,'type'=>$input['asset_type'],'title'=>$this->text($input['title']??null,150),'description'=>$this->text($input['description']??null,5000),'priority'=>$input['priority'],'assignee'=>$assignee['user_id'],'actor'=>$this->actor(),'created'=>$now,'updated'=>$now]);$result=$this->created('maintenance_ticket');$this->ticketHistory($result['id'],'ASSIGNED','Fault recorded and assigned.');return $result;
    });}
    private function ticketHistory(string $id,string $state,string $notes): void {$this->db->execute('INSERT INTO maintenance_history(company_id,ticket_id,state,notes,actor_user_id,occurred_at) VALUES(:company,:ticket,:state,:notes,:actor,:now)',['company'=>$this->company(),'ticket'=>$id,'state'=>$state,'notes'=>$notes,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);}
    public function ticketAction(string $id,string $action,array $input): array {return $this->atomic(function()use($id,$action,$input){
        $this->fields($input,['expected_revision','notes']);$ticket=$this->row('maintenance_tickets','ticket_id',$id);if($this->number($input['expected_revision']??null)!==(int)$ticket['revision'])throw HttpException::conflict('Ticket changed. Refresh first.');$notes=$this->text($input['notes']??null,2000);$states=['start'=>['ASSIGNED','IN_REPAIR'],'repair'=>['IN_REPAIR','AWAITING_VERIFICATION'],'verify'=>['AWAITING_VERIFICATION','VERIFIED']];
        if($action==='cancel'){if(in_array($ticket['state'],['VERIFIED','CANCELLED'],true))throw HttpException::conflict('Ticket already ended.');$state='CANCELLED';}else{if(!isset($states[$action]))throw HttpException::notFound();[$from,$state]=$states[$action];if($ticket['state']!==$from)throw HttpException::conflict('Invalid maintenance transition.');}
        if($action==='verify'){$repair=$this->db->fetch("SELECT actor_user_id FROM maintenance_history WHERE company_id=:company AND ticket_id=:id AND state='AWAITING_VERIFICATION' ORDER BY history_id DESC LIMIT 1",['company'=>$this->company(),'id'=>$id]);if($repair&&(string)$repair['actor_user_id']===$this->actor())throw HttpException::forbidden('The operator who recorded the repair cannot verify it.');}
        if($action==='verify'&&(string)$ticket['assignee_user_id']===$this->actor())throw HttpException::forbidden('A different operator must verify the repair.');$now=gmdate('Y-m-d H:i:s');$this->db->execute('UPDATE maintenance_tickets SET state=:state,revision=revision+1,updated_at=:now,verified_at=:verified,verified_by_user_id=:verifier WHERE company_id=:company AND ticket_id=:id',['state'=>$state,'now'=>$now,'verified'=>$action==='verify'?$now:null,'verifier'=>$action==='verify'?$this->actor():null,'company'=>$this->company(),'id'=>$id]);$this->ticketHistory($id,$state,$notes);$this->audit->record('maintenance_ticket',$action,$id);return ['state'=>$state,'revision'=>(int)$ticket['revision']+1];
    });}
    public function ticketHistoryList(string $id): array {$this->row('maintenance_tickets','ticket_id',$id);return $this->db->fetchAll('SELECT state,notes,actor_user_id,occurred_at FROM maintenance_history WHERE company_id=:company AND ticket_id=:id ORDER BY history_id',['company'=>$this->company(),'id'=>$id]);}
    public function serviceTarget(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['site_id','effective_from','response_minutes','patrols_per_day','guard_minutes_per_day']);$site=$this->site($input['site_id']??null);$date=$this->day($input['effective_from']??null);if($this->db->fetch('SELECT target_id FROM site_service_targets WHERE company_id=:company AND site_id=:site AND effective_from=:day',['company'=>$this->company(),'site'=>$site['site_id'],'day'=>$date]))throw HttpException::conflict('Targets already exist for this date. Add a later effective date for new terms.');$this->db->execute('INSERT INTO site_service_targets(company_id,site_id,effective_from,response_minutes,patrols_per_day,guard_minutes_per_day) VALUES(:company,:site,:day,:response,:patrols,:minutes)',['company'=>$this->company(),'site'=>$site['site_id'],'day'=>$date,'response'=>$this->number($input['response_minutes']??null,1,1440),'patrols'=>$this->number($input['patrols_per_day']??null,0,1000),'minutes'=>$this->number($input['guard_minutes_per_day']??null,0,1440000)]);return $this->created('site_service_target');
    });}
    public function serviceReport(array $input,bool $client=false): array {
        $this->fields($input,['site_id','date_from','date_to']);$site=$this->site($input['site_id']??null);if($client&&!$this->db->fetch('SELECT user_id FROM client_portal_access WHERE company_id=:company AND user_id=:actor AND client_id=:client',['company'=>$this->company(),'actor'=>$this->actor(),'client'=>$site['client_id']]))throw HttpException::notFound();$from=$this->day($input['date_from']??null);$to=$this->day($input['date_to']??null);if($to<$from||strtotime($to.' UTC')-strtotime($from.' UTC')>30*86400||$to>gmdate('Y-m-d'))throw HttpException::unprocessable('Choose up to 31 days ending today or earlier.');$days=[];
        for($date=$from;$date<=$to;$date=gmdate('Y-m-d',strtotime($date.' UTC')+86400)){
            $start=$date.' 00:00:00';$end=gmdate('Y-m-d H:i:s',strtotime($start.' UTC')+86400);$target=$this->db->fetch('SELECT target_id,response_minutes,patrols_per_day,guard_minutes_per_day FROM site_service_targets WHERE company_id=:company AND site_id=:site AND effective_from<=:day ORDER BY effective_from DESC LIMIT 1',['company'=>$this->company(),'site'=>$site['site_id'],'day'=>$date]);
            $params=['company'=>$this->company(),'site'=>$site['site_id'],'start'=>$start,'end'=>$end];$patrols=(int)$this->db->fetch("SELECT COUNT(*) AS total FROM patrol_sessions p JOIN patrol_routes r ON r.company_id=p.company_id AND r.patrol_route_id=p.patrol_route_id WHERE p.company_id=:company AND r.site_id=:site AND p.deleted_at IS NULL AND p.status='COMPLETED' AND p.started_at>=:start AND p.started_at<:end",$params)['total'];
            $attendance=$this->db->fetchAll('SELECT clock_in_at,clock_out_at FROM attendance WHERE company_id=:company AND site_id=:site AND deleted_at IS NULL AND clock_in_at<:end AND clock_out_at>:start',$params);$seconds=0;foreach($attendance as$a){$duration=strtotime($a['clock_out_at'].' UTC')-strtotime($a['clock_in_at'].' UTC');if($duration>0&&$duration<=172800)$seconds+=max(0,min(strtotime($a['clock_out_at'].' UTC'),strtotime($end.' UTC'))-max(strtotime($a['clock_in_at'].' UTC'),strtotime($start.' UTC')));}
            $jobs=$this->db->fetchAll("SELECT d.created_at,d.arrived_at,d.response_due_at FROM dispatch_jobs d JOIN incidents i ON i.company_id=d.company_id AND i.incident_id=d.incident_id WHERE d.company_id=:company AND i.site_id=:site AND d.state<>'CANCELLED' AND d.created_at>=:start AND d.created_at<:end",$params);$arrivals=0;$late=0;$elapsed=0;$pending=0;foreach($jobs as$j){if($j['arrived_at']!==null){$arrivals++;$duration=max(0,strtotime($j['arrived_at'].' UTC')-strtotime($j['created_at'].' UTC'));$elapsed+=$duration;if($target&&$duration>(int)$target['response_minutes']*60)$late++;}elseif($j['response_due_at']<gmdate('Y-m-d H:i:s'))$pending++;}
            $minutes=intdiv($seconds,60);$days[]=['date'=>$date,'target'=>$target,'recorded_guard_minutes'=>$minutes,'completed_patrol_starts'=>$patrols,'response_assignments'=>count($jobs),'arrivals'=>$arrivals,'average_response_seconds'=>$arrivals?intdiv($elapsed,$arrivals):null,'late_arrivals_against_target'=>$target?$late:null,'overdue_without_arrival'=>$pending,'guard_minute_shortfall'=>$target?max(0,(int)$target['guard_minutes_per_day']-$minutes):null,'patrol_shortfall'=>$target?max(0,(int)$target['patrols_per_day']-$patrols):null];
        }
        return ['site_id'=>$site['site_id'],'site_name'=>$site['site_name'],'days'=>$days,'generated_at'=>gmdate('Y-m-d H:i:s'),'note'=>'Recorded elapsed guard time, currently completed patrols by start date, and server-received response times. Today is partial. These observations do not independently verify presence, physical arrival, billing or contractual compliance. Missing targets mean unknown, not achieved.'];
    }
}
